export interface LinearWebhookPayload {
  action: string
  type: string
  createdAt: string
  organizationId: string
  webhookTimestamp: number
  webhookId: string
  url: string
  actor: {
    id: string
    type: string
    name: string
    email: string
    url: string
  }
  data: {
    id: string
    updatedAt: string
    number: number
    title: string
    priority: number
    estimate: number
    stateId: string
    assigneeId: string
    startedAt: string
    completedAt: string | null
  }
  updatedFrom: {
    stateId: string
    assigneeId: string
    startedAt: string | null
    updatedAt: string
  }
}

export interface LinearComment {
  author: { name: string }
  text: string
  createdAt: string
}

export interface ConnectorConfig {
  linearApiKey: string
  discordBotToken: string
  channelIdResolver: (issueId: string) => string | Promise<string>
  linearWebhookSecret?: string
  rawBody?: string
  linearSignature?: string
  fetch?: typeof fetch
  comments?: LinearComment[]
}

export interface HandleResult {
  messageId: string
  channelId: string
}

async function fetchAllComments(issueId: string, linearApiKey: string, fetchImpl: typeof fetch): Promise<LinearComment[]> {
  const query = `
    query IssueComments($issueId: ID!, $cursor: String) {
      issue(id: $issueId) {
        comments(first: 100, after: $cursor) {
          nodes {
            author { name }
            text
            createdAt
          }
          pageInfo {
            hasNextPage
            endCursor
          }
        }
      }
    }
  `
  const allComments: LinearComment[] = []
  let cursor: string | null = null
  let hasNextPage = true

  while (hasNextPage) {
    const response = await fetchImpl('https://api.linear.app/graphql', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${linearApiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query,
        variables: { issueId, cursor },
      }),
    })

    if (!response.ok) {
      throw new Error(`Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql`)
    }

    const data = await response.json() as {
      data?: {
        issue?: {
          comments?: {
            nodes: LinearComment[]
            pageInfo: { hasNextPage: boolean; endCursor: string }
          }
        }
      }
      errors?: Array<{ message: string }>
    }

    if (data.errors?.length) {
      throw new Error(`Linear GraphQL errors: ${data.errors.map(e => e.message).join(', ')}`)
    }

    const comments = data.data?.issue?.comments
    if (!comments) {
      break
    }

    allComments.push(...comments.nodes)
    hasNextPage = comments.pageInfo.hasNextPage
    cursor = comments.pageInfo.endCursor
  }

  return allComments
}

function formatDigest(issueRef: string, comments: LinearComment[]): string {
  const lines = [`Linear Issue ${issueRef} Closed`, '', 'Comments:']
  if (comments.length === 0) {
    lines.push('(no comments)')
  } else {
    for (const comment of comments) {
      lines.push(`- ${comment.author.name}: ${comment.text}`)
    }
  }
  return lines.join('\n')
}

function extractIssueRef(url: string, number: number): string {
  const match = url.match(/\/issue\/([^\/]+)$/)
  if (match) {
    return match[1]
  }
  return `ISSUE-${number}`
}

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload.action) throw new Error('Missing required field: action')
  if (!payload.type) throw new Error('Missing required field: type')
  if (!payload.data?.id) throw new Error('Missing required field: data.id')
  if (!payload.data?.number) throw new Error('Missing required field: data.number')
  if (!payload.data?.title) throw new Error('Missing required field: data.title')
  if (!payload.url) throw new Error('Missing required field: url')

  if (payload.action !== 'update') {
    throw new Error(`Expected action 'update', got '${payload.action}'`)
  }
  if (payload.type !== 'Issue') {
    throw new Error(`Expected type 'Issue', got '${payload.type}'`)
  }

  if (config.linearWebhookSecret && config.rawBody && config.linearSignature) {
    // Signature verification would go here (HMAC check of rawBody against linearSignature using linearWebhookSecret)
  }

  const issueId = payload.data.id
  const issueNumber = payload.data.number
  const issueRef = extractIssueRef(payload.url, issueNumber)

  let comments: LinearComment[] = []
  if (config.comments) {
    comments = config.comments
  } else if (config.linearApiKey) {
    const fetchImpl = config.fetch ?? fetch
    try {
      comments = await fetchAllComments(issueId, config.linearApiKey, fetchImpl)
    } catch (error) {
      console.log('[WARN] Failed to fetch Linear comments, proceeding with empty comment list:', error)
      comments = []
    }
  } else {
    throw new Error('linearApiKey is required to fetch comments')
  }

  const content = formatDigest(issueRef, comments)
  const channelId = await config.channelIdResolver(issueId)

  const fetchImpl = config.fetch ?? fetch
  const discordUrl = `https://discord.com/api/v10/channels/${channelId}/messages`
  const response = await fetchImpl(discordUrl, {
    method: 'POST',
    headers: {
      'Authorization': `Bot ${config.discordBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  })

  if (!response.ok) {
    throw new Error(`Discord API error: ${response.status} ${response.statusText} at POST ${discordUrl}`)
  }

  const result = await response.json() as { id: string; channelId: string }
  return { messageId: result.id, channelId: result.channelId }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, LinearWebhookPayload, LinearComment } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      linearApiKey: 'test-linear-key',
      discordBotToken: 'test-discord-token',
      channelIdResolver: (issueId) => `channel-${issueId}`,
      comments: [],
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.messageId).toBeDefined()
    expect(result.channelId).toBeDefined()
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    linearApiKey: 'linear-api-key',
    discordBotToken: 'discord-bot-token',
    channelIdResolver: (issueId) => `discord-channel-${issueId}`,
  }

  const issueId = '8f7e6d5c-4b3a-2198-7f6e-5d4c3b2a1098'
  const channelId = `discord-channel-${issueId}`

  const mockComments: LinearComment[] = [
    { author: { name: 'Alice' }, text: 'Fixed the auth bug', createdAt: '2025-01-24T16:00:00Z' },
    { author: { name: 'Bob' }, text: 'Added tests for edge cases', createdAt: '2025-01-24T16:30:00Z' },
  ]

  it('happy path: fetches comments via cursor pagination and posts digest to Discord', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql' && req.method === 'POST') {
        const body = req.json as { variables: { cursor?: string } }
        if (!body.variables.cursor) {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: [mockComments[0]],
                  pageInfo: { hasNextPage: true, endCursor: 'cursor-1' },
                },
              },
            },
          })
        } else if (body.variables.cursor === 'cursor-1') {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: [mockComments[1]],
                  pageInfo: { hasNextPage: false, endCursor: 'cursor-2' },
                },
              },
            },
          })
        }
        return jsonResponse({ data: { issue: { comments: { nodes: [], pageInfo: { hasNextPage: false, endCursor: '' } } } } })
      }
      if (req.url === `https://discord.com/api/v10/channels/${channelId}/messages` && req.method === 'POST') {
        return jsonResponse({ id: 'msg-123', channelId, content: 'digest' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch }
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)

    expect(result.messageId).toBe('msg-123')
    expect(result.channelId).toBe(channelId)

    const linearCalls = calls.filter(c => c.url === 'https://api.linear.app/graphql')
    expect(linearCalls.length).toBe(2)
    expect(linearCalls[0].json).toMatchObject({
      query: expect.any(String),
      variables: { issueId, cursor: undefined },
    })
    expect(linearCalls[1].json).toMatchObject({
      query: expect.any(String),
      variables: { issueId, cursor: 'cursor-1' },
    })

    const discordCall = calls.find(c => c.url.includes('/channels/') && c.url.endsWith('/messages'))
    expect(discordCall).toBeDefined()
    expect(discordCall!.method).toBe('POST')
    expect(discordCall!.headers.get('authorization')).toBe(`Bot ${baseConfig.discordBotToken}`)
    expect(discordCall!.json).toMatchObject({
      content: expect.stringContaining('Linear Issue ENG-123 Closed'),
    })
    expect(discordCall!.json.content).toContain('Alice: Fixed the auth bug')
    expect(discordCall!.json.content).toContain('Bob: Added tests for edge cases')
  })

  it('uses provided comments override and skips Linear API fetch', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === `https://discord.com/api/v10/channels/${channelId}/messages`) {
        return jsonResponse({ id: 'msg-456', channelId, content: 'digest' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch, comments: mockComments }
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)

    expect(result.messageId).toBe('msg-456')
    const linearCalls = calls.filter(c => c.url === 'https://api.linear.app/graphql')
    expect(linearCalls.length).toBe(0)
    expect(calls.some(c => c.url.includes('/channels/') && c.url.endsWith('/messages'))).toBe(true)
  })

  it('throws on missing required field: action', async () => {
    const payload = { ...SOURCE_EXAMPLE, action: undefined } as unknown as LinearWebhookPayload
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: action')
  })

  it('throws on missing required field: data.id', async () => {
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, id: undefined } } as unknown as LinearWebhookPayload
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: data.id')
  })

  it('throws on invalid action type', async () => {
    const payload = { ...SOURCE_EXAMPLE, action: 'create' } as unknown as LinearWebhookPayload
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow("Expected action 'update', got 'create'")
  })

  it('throws on invalid type', async () => {
    const payload = { ...SOURCE_EXAMPLE, type: 'Project' } as unknown as LinearWebhookPayload
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow("Expected type 'Issue', got 'Project'")
  })

  it('throws on non-2xx Discord response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({ data: { issue: { comments: { nodes: [], pageInfo: { hasNextPage: false, endCursor: '' } } } } })
      }
      if (req.url.includes('/channels/') && req.url.endsWith('/messages')) {
        return jsonResponse({ error: 'Unauthorized' }, 401)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch, comments: [] }
    await expect(handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)).rejects.toThrow('Discord API error: 401 Unauthorized at POST')
  })

  it('throws on non-2xx Linear API response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({ error: 'Invalid token' }, 401)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch }
    await expect(handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)).rejects.toThrow('Linear API error: 401 Unauthorized at POST https://api.linear.app/graphql')
  })

  it('falls back to empty comments when Linear API fetch fails', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({ error: 'Server error' }, 500)
      }
      if (req.url.includes('/channels/') && req.url.endsWith('/messages')) {
        return jsonResponse({ id: 'msg-789', channelId, content: 'digest' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch }
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)

    expect(result.messageId).toBe('msg-789')
    const linearCalls = calls.filter(c => c.url === 'https://api.linear.app/graphql')
    expect(linearCalls.length).toBe(1)
    const discordCall = calls.find(c => c.url.includes('/channels/') && c.url.endsWith('/messages'))
    expect(discordCall).toBeDefined()
    expect(discordCall!.json.content).toContain('(no comments)')
  })

  it('extracts issue reference from URL', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/channels/') && req.url.endsWith('/messages')) {
        return jsonResponse({ id: 'msg-1', channelId, content: 'digest' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload = {
      ...SOURCE_EXAMPLE,
      url: 'https://linear.app/company/issue/PROJ-456',
      data: { ...SOURCE_EXAMPLE.data, number: 456 },
    } as unknown as LinearWebhookPayload

    const config = { ...baseConfig, fetch, comments: [] }
    await handle(payload, config)

    const discordCall = calls.find(c => c.url.includes('/channels/') && c.url.endsWith('/messages'))
    expect(discordCall).toBeDefined()
    expect(discordCall!.json.content).toContain('Linear Issue PROJ-456 Closed')
  })
})

