async function fetchAllComments(issueId: string, linearApiKey: string, fetchImpl: typeof fetch): Promise<LinearComment[]> {
  const query = `
    query IssueComments($issueId: ID!, $cursor: String) {
      issue(id: $issueId) {
        comments(first: 100, after: $cursor) {
          nodes {
            author { name }
            text
            createdAt
          }
          pageInfo {
            hasNextPage
            endCursor
          }
        }
      }
    }
  `
  const allComments: LinearComment[] = []
  let cursor: string | null = null
  let hasNextPage = true

  while (hasNextPage) {
    const response = await fetchImpl('https://api.linear.app/graphql', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${linearApiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query,
        variables: { issueId, cursor },
      }),
    })

    if (!response.ok) {
      throw new Error(`Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql`)
    }

    const data = await response.json() as {
      data?: {
        issue?: {
          comments?: {
            nodes: LinearComment[]
            pageInfo: { hasNextPage: boolean; endCursor: string }
          }
        }
      }
      errors?: Array<{ message: string }>
    }

    if (data.errors?.length) {
      throw new Error(`Linear GraphQL errors: ${data.errors.map(e => e.message).join(', ')}`)
    }

    const comments = data.data?.issue?.comments
    if (!comments) {
      break
    }

    allComments.push(...comments.nodes)
    hasNextPage = comments.pageInfo.hasNextPage
    cursor = comments.pageInfo.endCursor
  }

  return allComments
}

function formatDigest(issueRef: string, comments: LinearComment[]): string {
  const lines = [`Linear Issue ${issueRef} Closed`, '', 'Comments:']
  if (comments.length === 0) {
    lines.push('(no comments)')
  } else {
    for (const comment of comments) {
      lines.push(`- ${comment.author.name}: ${comment.text}`)
    }
  }
  return lines.join('\n')
}

function extractIssueRef(url: string, number: number): string {
  const match = url.match(/\/issue\/([^\/]+)$/)
  if (match) {
    return match[1]
  }
  return `ISSUE-${number}`
}

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload.action) throw new Error('Missing required field: action')
  if (!payload.type) throw new Error('Missing required field: type')
  if (!payload.data?.id) throw new Error('Missing required field: data.id')
  if (!payload.data?.number) throw new Error('Missing required field: data.number')
  if (!payload.data?.title) throw new Error('Missing required field: data.title')
  if (!payload.url) throw new Error('Missing required field: url')

  if (payload.action !== 'update') {
    throw new Error(`Expected action 'update', got '${payload.action}'`)
  }
  if (payload.type !== 'Issue') {
    throw new Error(`Expected type 'Issue', got '${payload.type}'`)
  }

  if (config.linearWebhookSecret && config.rawBody && config.linearSignature) {
    // Signature verification would go here (HMAC check of rawBody against linearSignature using linearWebhookSecret)
  }

  const issueId = payload.data.id
  const issueNumber = payload.data.number
  const issueRef = extractIssueRef(payload.url, issueNumber)

  let comments: LinearComment[] = []
  if (config.comments) {
    comments = config.comments
  } else if (config.linearApiKey) {
    const fetchImpl = config.fetch ?? fetch
    try {
      comments = await fetchAllComments(issueId, config.linearApiKey, fetchImpl)
    } catch (error) {
      console.log('[WARN] Failed to fetch Linear comments, proceeding with empty comment list:', error)
      comments = []
    }
  } else {
    throw new Error('linearApiKey is required to fetch comments')
  }

  const content = formatDigest(issueRef, comments)
  const channelId = await config.channelIdResolver(issueId)

  const fetchImpl = config.fetch ?? fetch
  const discordUrl = `https://discord.com/api/v10/channels/${channelId}/messages`
  const response = await fetchImpl(discordUrl, {
    method: 'POST',
    headers: {
      'Authorization': `Bot ${config.discordBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  })

  if (!response.ok) {
    throw new Error(`Discord API error: ${response.status} ${response.statusText} at POST ${discordUrl}`)
  }

  const result = await response.json() as { id: string; channelId: string }
  return { messageId: result.id, channelId: result.channelId }
}

