    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({ data: { issue: { comments: { nodes: [], pageInfo: { hasNextPage: false, endCursor: '' } } } } })
      }
      if (req.url.includes('/channels/') && req.url.endsWith('/messages')) {
        return jsonResponse({ error: 'Unauthorized' }, 401)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch, comments: [] }
    await expect(handle(typedSourceExample, config)).rejects.toThrow('Discord API error: 401 Unauthorized at POST')
  })

  it('falls back to empty comments when Linear API fetch fails', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({ error: 'Server error' }, 500)
      }
      if (req.url.includes('/channels/') && req.url.endsWith('/messages')) {
        return jsonResponse({ id: 'msg-789', channelId, content: 'digest' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch }
    const result = await handle(typedSourceExample, config)

    expect(result.messageId).toBe('msg-789')
    const linearCalls = calls.filter(c => c.url === 'https://api.linear.app/graphql')
    expect(linearCalls.length).toBe(1)
    const discordCall = calls.find(c => c.url.includes('/channels/') && c.url.endsWith('/messages'))
    expect(discordCall).toBeDefined()
    expect((discordCall!.json as Record<string, unknown>).content).toContain('(no comments)')
  })

  it('extracts issue reference from URL', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/channels/') && req.url.endsWith('/messages')) {
        return jsonResponse({ id: 'msg-1', channelId, content: 'digest' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload = {
      ...SOURCE_EXAMPLE,
      url: 'https://linear.app/company/issue/PROJ-456',
      data: { ...SOURCE_EXAMPLE.data, number: 456 },
    } as unknown as LinearWebhookPayload

    const config = { ...baseConfig, fetch, comments: [] }
    await handle(payload, config)

    const discordCall = calls.find(c => c.url.includes('/channels/') && c.url.endsWith('/messages'))
    expect(discordCall).toBeDefined()
    expect((discordCall!.json as Record<string, unknown>).content).toContain('Linear Issue PROJ-456 Closed')
  })
})

